filters=''.join(f'<button role="tab" id="tab-{k}" data-filter="{k}" aria-selected="{str(k=="all").lower()}" aria-controls="catalog-results" tabindex="{0 if k=="all" else -1}">{v}</button>' for k,v in [('all','Все'),('female','Женские'),('male','Мужские'),('niche','Нишевые'),('universal','Универсальные')])
